import{_ as e,o as t,c as a,aw as l}from"./chunks/framework.DLufY-ao.js";const m=JSON.parse('{"title":"BDD","description":"","frontmatter":{},"headers":[],"relativePath":"wiki/dev-commit/testing/testing/concepts/bdd.md","filePath":"wiki/dev-commit/testing/testing/concepts/bdd.md"}'),o={name:"wiki/dev-commit/testing/testing/concepts/bdd.md"};function r(n,i,d,s,c,D){return t(),a("div",null,[...i[0]||(i[0]=[l('<h1 id="bdd" tabindex="-1">BDD <a class="header-anchor" href="#bdd" aria-label="Permalink to &quot;BDD&quot;">​</a></h1><ul><li><strong>Behavior-Driven Development, BDD (Разработка через поведение)</strong> - методология разработки программного обеспечения, являющаяся ответвлением от методологии разработки через тестирование (TDD) в том смысле, что перед тем как написать какой-либо тест необходимо сначала описать желаемый результат от добавляемой функциональности на предметно-ориентированном языке. После того как это будет проделано, конструкции этого языка переводятся специалистами или специальным программным обеспечением в описание теста</li><li>Идея: совмещение в процессе разработки чисто технических интересов и интересов бизнеса, позволяя тем самым управляющему персоналу и программистам говорить на одном языке. Для общения между этими группами персонала используется предметно-ориентированный язык, основу которого представляют конструкции из естественного языка, понятные неспециалисту, обычно выражающие поведение программного продукта и ожидаемые результаты</li><li>Считается, что данный подход эффективен, когда предметная область, в которой работает программный продукт, описывается очень комплексно</li><li>BDD предполагает описание тестировщиком или аналитиком пользовательских сценариев на естественном языке - если можно так выразиться, на языке бизнеса</li><li>BDD - у тебя уже есть написанный код, и заказчик попросил тебя протестить какие-то определённые бизнес-фичи, и ты начинаешь писать тесты именно под них</li><li>Jasmine - реализация на JavaScript</li></ul><h3 id="bdd-фокусируется-на-следующих-вопросах" tabindex="-1">BDD фокусируется на следующих вопросах <a class="header-anchor" href="#bdd-фокусируется-на-следующих-вопросах" aria-label="Permalink to &quot;BDD фокусируется на следующих вопросах&quot;">​</a></h3><ol><li>С чего начинается процесс</li><li>Что нужно тестировать, а что нет</li><li>Сколько проверок должно быть совершено за один раз</li><li>Что можно назвать проверкой</li><li>Как понять, почему тест не прошёл</li></ol><h3 id="принципы" tabindex="-1">Принципы <a class="header-anchor" href="#принципы" aria-label="Permalink to &quot;Принципы&quot;">​</a></h3><ol><li>Заголовок (Title) - описание бизнес-цели</li><li>Описание (Narrative) раскрыты следующие вопросы: - Кто является заинтересованным лицом данной истории - Что входит в состав данной истории - Какую ценность данная история предоставляет для бизнеса</li><li>Сценарии (Scenarios) может быть один и более сценариев, каждый из которых раскрывает одну из ситуаций поведения пользователя, тем самым конкретизируя описание спецификации. Каждый сценарий обычно строится по одной и той же схеме: - Начальные условия (одно или несколько) - Событие, которое инициирует начало этого сценария - Ожидаемый результат или результаты</li></ol>',6)])])}const h=e(o,[["render",r]]);export{m as __pageData,h as default};
